CREATE TABLE public.fishing_licenses (
    id integer NOT NULL,
    state text NOT NULL,
    state_abbr text NOT NULL,
    resident_annual_cost numeric(8,2),
    non_resident_annual_cost numeric(8,2),
    resident_daily_cost numeric(8,2),
    non_resident_daily_cost numeric(8,2),
    youth_exemption_age integer,
    senior_exemption_age integer,
    senior_discount_pct integer DEFAULT 0,
    free_fishing_days text,
    agency_name text NOT NULL,
    agency_url text NOT NULL,
    purchase_url text,
    notes text,
    freshwater_endorsement boolean DEFAULT false,
    saltwater_endorsement boolean DEFAULT false,
    trout_stamp_required boolean DEFAULT false,
    trout_stamp_cost numeric(8,2),
    updated_at timestamp with time zone DEFAULT now(),
    created_at timestamp with time zone DEFAULT now()
);

CREATE SEQUENCE public.fishing_licenses_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.fishing_licenses_id_seq OWNED BY public.fishing_licenses.id;


ALTER TABLE ONLY public.fishing_licenses ALTER COLUMN id SET DEFAULT nextval('public.fishing_licenses_id_seq'::regclass);

ALTER TABLE ONLY public.fishing_licenses ADD CONSTRAINT fishing_licenses_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.fishing_licenses ADD CONSTRAINT fishing_licenses_state_key UNIQUE (state);

SELECT setval('public.fishing_licenses_id_seq', COALESCE(MAX(id), 1), MAX(id) IS NOT NULL) FROM public.fishing_licenses;